import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor gelu_tanh_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float gelu_scalar(float x) {
    const float kAlpha = 0.7978845608028654f; // sqrt(2/pi)
    const float kBeta  = 0.044715f;
    float x3 = x * x * x;
    float inner = kAlpha * (x + kBeta * x3);
    // Fast tanh via __expf intrinsic: tanh(z) = 1 - 2/(exp(2z)+1)
    float e = __expf(-2.0f * fabsf(inner));
    float t = copysignf(1.0f - 2.0f * e / (1.0f + e), inner);
    return 0.5f * x * (1.0f + t);
}

// Vectorized kernel: processes float4 chunks using CUTE tensors over global memory.
// Thread-level unrolling (UNROLL elements per iteration) increases instruction-level
// parallelism and reduces grid-stride loop overhead, improving effective memory
// throughput without changing numerical semantics.
__global__ void gelu_tanh_vec4_kernel(const float4* __restrict__ X,
                                       float4* __restrict__ Y,
                                       int64_t N4)
{
    constexpr int UNROLL = 4;
    // Represent the vectorized buffers as 1D CUTE tensors.
    Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(N4), make_stride(Int<1>{}));
    Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(N4), make_stride(Int<1>{}));
    int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    for (; idx < N4; idx += stride * UNROLL) {
        #pragma unroll
        for (int u = 0; u < UNROLL; ++u) {
            int64_t cur = idx + (int64_t)u * stride;
            if (cur < N4) {
                float4 v = mX(cur);
                float4 r;
                r.x = gelu_scalar(v.x);
                r.y = gelu_scalar(v.y);
                r.z = gelu_scalar(v.z);
                r.w = gelu_scalar(v.w);
                mY(cur) = r;
            }
        }
    }
}

// Scalar tail kernel for remaining elements (N % 4 != 0), also using CUTE tensors.
__global__ void gelu_tanh_scalar_kernel(const float* __restrict__ X,
                                         float* __restrict__ Y,
                                         int64_t offset,
                                         int64_t N)
{
    Tensor mX = make_tensor(make_gmem_ptr(X + offset), make_shape(N - offset), make_stride(Int<1>{}));
    Tensor mY = make_tensor(make_gmem_ptr(Y + offset), make_shape(N - offset), make_stride(Int<1>{}));

    int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    int64_t total  = N - offset;

    for (; idx < total; idx += stride) {
        float v = mX(idx);
        mY(idx) = gelu_scalar(v);
    }
}

torch::Tensor gelu_tanh_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

    auto x_c = x.contiguous();
    auto y   = torch::empty_like(x_c);

    int64_t N  = x_c.numel();
    int64_t N4 = N / 4;
    int64_t rem_offset = N4 * 4;

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    if (N4 > 0) {
        const float4* x_ptr4 = reinterpret_cast<const float4*>(x_c.data_ptr<float>());
        float4* y_ptr4       = reinterpret_cast<float4*>(y.data_ptr<float>());

        int threads = 256;
        int64_t blocks64 = (N4 + threads - 1) / threads;
        int max_blocks = 65535 * 32; // generous cap
        int blocks = (int)(blocks64 > max_blocks ? max_blocks : blocks64);
        if (blocks < 1) blocks = 1;

        gelu_tanh_vec4_kernel<<<blocks, threads, 0, stream>>>(x_ptr4, y_ptr4, N4);

        auto err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, "gelu_tanh_vec4_kernel launch failed: ", cudaGetErrorString(err));
    }

    if (rem_offset < N) {
        const float* x_ptr = x_c.data_ptr<float>();
        float* y_ptr        = y.data_ptr<float>();

        int64_t rem = N - rem_offset;
        int threads = 128;
        int64_t blocks64 = (rem + threads - 1) / threads;
        int blocks = (int)(blocks64 < 1 ? 1 : blocks64);

        gelu_tanh_scalar_kernel<<<blocks, threads, 0, stream>>>(x_ptr, y_ptr, rem_offset, N);

        auto err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, "gelu_tanh_scalar_kernel launch failed: ", cudaGetErrorString(err));
    }

    return y;
}
"""

gelu_ext = load_inline(
    name="cute_gelu_tanh_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["gelu_tanh_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    GELU (tanh approximation, minGPT/BERT-style) implemented with a single
    fused custom CUDA kernel using CuTe tensor abstractions.
    """
    def __init__(self) -> None:
        super().__init__()
        self._ext = gelu_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.gelu_tanh_forward(x)

